script:
frappe.ui.form.on("Opportunity", {
    // Set item_code filter based on custom_design after form loads
	onload_post_render: function (frm) {
		// Get the all the information of the item_code link field
		frm.fields_dict["items"].grid.get_field("item_code").get_query = function (doc, cdt, cdn) {
			const Lrow = locals[cdt][cdn];
			return {
				filters: { // set filter for the custom_design
					custom_design: Lrow.custom_design
				}
			};
		};
	}
});

// Ensure the item_code filter is also applied when a new row is rendered in the child table
frappe.ui.form.on("Opportunity Item", {
	form_render: function (frm, cdt, cdn) {
	    // Re-apply the item_code filter when a new row is rendered
		// This ensures filtering based on the row's custom_design value
		frm.fields_dict["items"].grid.get_field("item_code").get_query = function (doc, cdt, cdn) {
			const Lrow = locals[cdt][cdn];
			return {
				filters: {
					custom_design: Lrow.custom_design
				}
			};
		};
	},
	custom_design: function(frm, cdt, cdn){
	    frm.fields_dict["items"].grid.get_field("item_code").get_query = function (doc, cdt, cdn) {
			const Lrow = locals[cdt][cdn];
			return {
				filters: {
					custom_design: Lrow.custom_design
				}
			};
		};
	}
});
